const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
const badge=(text,state='')=>`<span class="badge ${esc(state)}"><span class="dot"></span>${esc(text)}</span>`;
const tag=text=>`<span class="tag">${esc(text)}</span>`;
const button=(label,act,extra='',cls='')=>`<button type="button" class="btn ${cls}" data-act="${act}" ${extra}>${label}</button>`;
const fmt=t=>t?new Date(t).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const stateName={pass:'符合已收录条件',conditional:'满足指定条件后可申请',unknown:'待核实',fail:'当前不满足'};
