let data=null,csrf='',auth=null,queryDraft=null,queryResult=null,match=null,studentDraft=null,editDraft=null,modalReturn=null,selectedCompare=new Set(),routeEpoch=0,showDetailedSources=false;
const exams=['TOEFL iBT','IELTS Academic Module','Duolingo English Test','TOEIC L&R','PTE Academic','Cambridge B2 First','Cambridge C1 Advanced','Cambridge C2 Proficiency','SAT EBRW','ACT English'];
