const student=id=>data.students.find(s=>s.id===id);
const pathValue=(o,p)=>p.split('.').reduce((v,k)=>v?.[k],o);
function setValue(o,p,v){const a=p.split('.');let t=o;for(const k of a.slice(0,-1))t=t[k]??={};t[a.at(-1)]=v;}
async function api(path,body,method){const r=await fetch('/api'+path,{method:method||(body?'POST':'GET'),headers:{'Content-Type':'application/json','X-SGU-Request':'1','X-CSRF-Token':csrf},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok){const e=new Error(d.error||'请求失败');e.current=d.current;e.status=r.status;throw e;}return d;}
function toast(message){$('#toast').innerHTML=`<div class="toast">${esc(message)}</div>`;setTimeout(()=>$('#toast').innerHTML='',4500);}
function empty(title,detail=''){return `<div class="empty">${icon('search')}<strong>${esc(title)}</strong><p>${esc(detail)}</p></div>`;}
function evidence(src){return src?`<button class="evidence-btn" data-act="evidence" data-source="${esc(JSON.stringify(src))}">原文 p.${esc(src.page)}</button>`:'';}
function field(label,name,value='',type='text',help=''){return `<div class="field"><label for="f-${esc(name)}">${esc(label)}</label><input id="f-${esc(name)}" name="${esc(name)}" type="${type}" value="${esc(value)}" ${type==='number'?'step="any" min="0"':''}>${help?`<small>${esc(help)}</small>`:''}</div>`;}
function select(label,name,value,options,help=''){return `<div class="field"><label for="f-${esc(name)}">${esc(label)}</label><select id="f-${esc(name)}" name="${esc(name)}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value??'')===String(v)?'selected':''}>${esc(l)}</option>`;}).join('')}</select>${help?`<small>${esc(help)}</small>`:''}</div>`;}
const triField=(label,name,value,help='')=>select(label,name,value,[['','待核实'],['true','是'],['false','否']],help);
function textArea(label,name,value,rows=4){return `<div class="field"><label for="f-${esc(name)}">${esc(label)}</label><textarea id="f-${esc(name)}" name="${esc(name)}" rows="${rows}">${esc(value)}</textarea></div>`;}
function showModal(title,body,wide=false){modalReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-act="close" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.modal input,.modal textarea,.modal select,.modal button')?.focus(),30);}
function closeModal(){if($('.modal [data-dirty="true"]')&&!confirm('关闭会丢弃尚未保存的修改。继续关闭？'))return;$('#modal-root').innerHTML='';document.body.style.overflow='';modalReturn?.focus();studentDraft=null;editDraft=null;}
function formError(form,message){let el=form.querySelector('.error-box');if(!el){el=document.createElement('div');el.className='error-box';el.setAttribute('role','alert');form.prepend(el);}el.textContent=message;el.scrollIntoView({block:'nearest'});}
async function refreshData(){data=await api('/bootstrap');csrf=data.csrf;auth=data.user;}
function shell(){const r=location.hash.slice(1).split('/')[0]||'students';const active=r==='student'?'students':r==='program'?'programs':r;const menu=[['students','students','学生与匹配'],['ask','ask','条件问答'],['programs','school','学校与项目'],['library','file','资料维护'],['history','history','修改记录']];const current=menu.find(m=>m[0]===active)?.[2]||(active==='settings'?'团队设置':'工作台');$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a href="#students" class="brand"><span class="brand-mark">${icon('graduation')}</span><span class="brand-text"><strong>SGU</strong><small>日本本科选校工作台</small></span></a><div class="nav-title">顾问工作空间</div><nav class="nav" aria-label="主导航">${menu.map(([id,ic,name])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''} title="${name}">${icon(ic)}<span>${name}</span></a>`).join('')}</nav><div class="side-bottom"><a href="#settings">${icon('settings')}<span>团队设置</span></a><div class="side-note"><strong>每个判断，都有出处。</strong>依据已核对的招生要求<br>保留原文与规则版本</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumbs"><span>选校工作台</span>${icon('chevron')}<span>${current}</span></div><div class="top-user"><span class="top-date">${new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'})}</span><div class="avatar">${esc(auth.login.slice(0,1))}</div><span>${esc(auth.login)}</span><button class="icon-btn" data-act="logout" aria-label="退出登录" title="退出登录">${icon('logout')}</button></div></header><div id="update-banner"></div><main id="main" class="main" tabindex="-1"></main></div></div>`;}
function pageHead(title,subtitle,actions=''){return `<div class="pagehead"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="flex">${actions}</div></div>`;}
function dashboard(){const sourceRules=new Set(data.programs.flatMap(p=>p.requirements.map(r=>r.id))).size;$('#main').innerHTML=pageHead('学生与匹配','从学生的实际情况出发，逐项核对可申请的项目。',button(icon('plus')+' 新建学生','new-student','','primary'))+`<div class="stats"><div class="stat"><span>团队学生</span><strong>${data.students.length}</strong><small>位</small></div><div class="stat"><span>已收录项目</span><strong>${data.programs.length}</strong><small>个</small></div><div class="stat"><span>语言考试门槛</span><strong>${data.programs.reduce((a,p)=>a+p.language.length,0)}</strong><small>条</small></div><div class="stat"><span>招生轮次</span><strong>${data.programs.reduce((a,p)=>a+p.rounds.length,0)}</strong><small>组</small></div></div><div class="workspace-columns"><div><section class="panel section"><div class="panel-head"><h2>学生档案</h2><span class="muted small">团队共享 · 修改可追溯</span></div><div class="toolbar"><div class="tabs"><button class="tab active" data-act="student-filter" data-filter="all">全部学生</button><button class="tab" data-act="student-filter" data-filter="real">实际学生</button><button class="tab" data-act="student-filter" data-filter="example">示例档案</button></div><label class="search">${icon('search')}<input id="student-search" aria-label="搜索学生" placeholder="搜索姓名、学校或课程"></label></div><div id="student-list"></div></section><div class="note">匹配结果分别展示申请资格、申请窗口、材料待办和个人偏好。示例档案为虚构数据，可用于了解操作。</div></div><aside class="right-rail"><section class="panel mini section"><h3>当前项目库</h3><p>立命馆大学 · 2027 入学<br>AO Admissions（英语）</p>${data.programs.map(p=>`<a href="#program/${p.id}" class="project-mini"><span class="monogram">${p.id}</span><div><strong>${esc(p.name)}</strong><div class="muted">${esc(p.direction)}</div></div>${icon('chevron')}</a>`).join('')}</section><section class="panel mini section"><h3>先问一个问题</h3><p style="margin-bottom:13px">不确定从哪里找？把筛选条件直接写出来。</p>${['不需要SAT或ACT的项目','哪些项目不需要面试？','雅思6分能考虑哪些项目？'].map(q=>`<button class="quick-question" data-act="ask-preset" data-question="${esc(q)}">${esc(q)}${icon('arrow')}</button>`).join('')}</section></aside></div>`;renderStudentRows();}
let studentFilter='all';
function renderStudentRows(){const term=($('#student-search')?.value||'').toLowerCase();const ss=data.students.filter(s=>(studentFilter==='all'||studentFilter==='example'&&s.isExample||studentFilter==='real'&&!s.isExample)&&[s.name,s.school,s.curriculum].join(' ').toLowerCase().includes(term));$('#student-list').innerHTML=ss.length?`<div class="table-wrap"><table class="student-table"><thead><tr><th>学生 / 就读学校</th><th>课程与成绩</th><th>目标入学</th><th>操作</th></tr></thead><tbody>${ss.map(s=>`<tr><td><a href="#student/${s.id}" class="student-name"><span class="avatar">${esc(s.name.slice(0,1))}</span><span><strong>${esc(s.name)}</strong> ${s.isExample?tag('示例'):''}<small>${esc(s.school||'学校待补充')}</small></span></a></td><td><div>${esc(s.curriculum||'课程待补充')}</div><small class="muted">${esc(s.exams?.length?s.exams.map(e=>`${e.exam==='IELTS Academic Module'?'IELTS':e.exam} ${e.score??'—'}`).join(' / '):'语言成绩待补充')}</small></td><td>${esc(s.intake||'待确定')}<small class="muted" style="display:block">${esc(s.educationStatus==='expected'?'预计毕业':s.educationStatus==='completed'?'已取得资格':'毕业状态待核实')}</small></td><td><a class="btn sm" href="#student/${s.id}">查看档案 ${icon('chevron')}</a></td></tr>`).join('')}</tbody></table></div>`:empty('没有找到学生','新建档案，或调整搜索条件。');}
async function profile(id){const s=student(id);if(!s){$('#main').innerHTML=empty('学生不存在');return;}$('#main').innerHTML=pageHead(s.name+'的选校档案','资料未填写的部分保持待核实，目标分数仅用于模拟。',button(icon('edit')+' 编辑资料','edit-student',`data-id="${id}"`)+button(icon('refresh')+' 开始匹配','match',`data-id="${id}"`,'primary'))+`<section class="panel section"><div class="profile-hero"><div class="avatar">${esc(s.name[0])}</div><div><div class="flex"><h2>${esc(s.name)}</h2>${s.isExample?tag('虚构示例'):''}${tag(s.intake||'入学期待定')}</div><p class="muted">${esc(s.school||'学校未填写')}　${esc(s.curriculum||'课程待核实')}</p></div></div><div class="profile-grid">${[['资格类型',s.qualification||'未填写'],['资格取得',s.graduationDate||'日期待核实'],['国籍',(s.nationalities||[]).join(' / ')||'未填写'],['语言成绩',s.exams?.map(e=>`${e.exam} ${e.score??'—'}`).join(' / ')||'未填写']].map(([l,v])=>`<div class="info-cell"><small>${l}</small><strong>${esc(v)}</strong></div>`).join('')}</div></section><div class="tabs section"><button class="tab active" data-act="profile-tab" data-tab="results">项目匹配</button><button class="tab" data-act="profile-tab" data-tab="materials">材料准备</button><button class="tab" data-act="profile-tab" data-tab="candidates">候选清单 <span class="small">${s.candidates?.length||0}</span></button><button class="tab" data-act="profile-tab" data-tab="history">匹配历史</button></div><div id="profile-content" data-student="${id}">${empty('开始一次有依据的匹配','点击“开始匹配”，逐项检查学历、语言和身份条件。')}</div>`;match=null;}
let resultFilter='all';
function checkRows(checks){return checks.map(c=>`<div class="check ${esc(c.state)}">${icon(c.state==='pass'?'check':c.state==='fail'?'close':c.state==='conditional'?'clock':'alert')}<div><strong>${esc(c.label)}</strong>${c.reason?`<p class="muted small">${esc(c.reason)}</p>`:''}</div>${evidence(c.source)}</div>`).join('');}
function renderMatches(){const results=match.results.filter(r=>resultFilter==='all'||r.state===resultFilter);const stale=match.programs.some(p=>program(p.id)?.version!==p.version);const s=match.student;$('#profile-content').innerHTML=`${match.simulation?'<div class="note warning section">模拟匹配包含目标分数，不代表学生已经取得对应成绩。</div>':''}${stale?'<div class="note warning section">部分项目规则已有更新。这份结果保留原版本，可重新匹配比较。</div>':''}<div class="between section wrap"><div><h2>匹配结果 <span class="muted small">${match.results.length} 个项目轮次</span></h2><p class="muted small">${fmt(match.createdAt)} · ${esc(match.actor)} · 学生资料 v${s.revision}</p></div><div class="flex">${button('用目标成绩模拟','simulate',`data-id="${s.id}"`,'sm')}${button(icon('download')+' 导出结果','export-match','','sm')}</div></div><div class="tabs section">${[['all','全部'],['pass','符合条件'],['conditional','附条件'],['unknown','待核实'],['fail','当前不满足']].map(([k,n])=>`<button class="tab ${resultFilter===k?'active':''}" data-act="result-filter" data-filter="${k}">${n} <small>${k==='all'?match.results.length:match.results.filter(r=>r.state===k).length}</small></button>`).join('')}</div><section class="panel">${results.length?results.map((r,i)=>{const p=match.programs.find(p=>p.id===r.programId);const key=`${r.programId}:${r.roundId}`;return `<article class="result"><div class="result-summary"><span class="monogram">${r.programId}</span><div class="grow"><h3><a href="#program/${r.programId}">${esc(r.programName)}</a></h3><p>${esc(r.intake)} 入学 · 第${r.round}轮 · 规则 v${r.version}${r.path?` · 资格路径 ${r.path}`:''}</p></div>${badge(stateName[r.state],r.state)}${badge(r.window.label,r.window.status)}<button class="icon-btn" data-act="toggle-result" data-index="${match.results.indexOf(r)}" aria-label="展开${esc(r.programName)}判断依据" aria-expanded="false">${icon('chevron')}</button></div><div class="result-details hidden" id="result-${match.results.indexOf(r)}"><div class="grid2 section"><div class="check-group"><h4>学历路径 ${badge(stateName[r.education.state],r.education.state)}</h4>${r.education.paths.map(path=>`<details ${path.state==='pass'||path.state==='conditional'?'open':''}><summary>${path.id} · ${esc(path.label)} ${badge(stateName[path.state],path.state)}</summary>${checkRows(path.checks)}</details>`).join('')}</div><div class="check-group"><h4>英语证明 ${badge(stateName[r.language.state],r.language.state)}</h4>${r.language.attempts.length?r.language.attempts.map(a=>`<div class="check ${a.state}">${icon(a.state==='pass'?'check':'alert')}<div><strong>${esc(a.label)}</strong><p class="muted small">${esc(a.reason)}</p>${checkRows(a.checks||[])}</div>${evidence(a.source)}</div>`).join(''):'<p class="muted small">未提供可用的实际考试成绩</p>'}${r.language.waivers.map(w=>`<details><summary>${esc(w.label)} ${badge(stateName[w.state],w.state)}</summary>${checkRows(w.checks)}</details>`).join('')}</div></div>${r.hard.length?`<div class="check-group section"><h4>其他适用条件</h4>${checkRows(r.hard)}</div>`:''}${r.conditions.length?`<div class="note section">${r.conditions.map(esc).join('<br>')}</div>`:''}${r.missing.length?`<div class="note warning section">待核实：${r.missing.map(esc).join('；')}</div>`:''}<div class="grid2 section"><div><h4>申请窗口</h4><p class="muted small">${p.rounds.find(x=>x.id===r.roundId)?.applyStart} 10:00 至 ${p.rounds.find(x=>x.id===r.roundId)?.applyEnd} 23:00（日本时间）</p></div><div><h4>材料与偏好</h4><p class="muted small">必需材料待准备 ${r.materials.filter(m=>m.required&&m.preparation!=='ready'&&m.stage==='申请').length} 项；不改变资格结论。</p>${r.preferences.map(pr=>`<p class="small">${esc(pr.label)}：${badge(pr.state==='pass'?'符合偏好':pr.state==='fail'?'不符偏好':'待核实',pr.state)} ${esc(pr.reason)}</p>`).join('')}</div></div><div class="between wrap"><a class="link" href="#program/${r.programId}">查看完整项目要求</a>${button((student(s.id).candidates||[]).includes(key)?'移出候选清单':'加入候选清单','candidate',`data-key="${key}" data-student="${s.id}"`,'sm')}</div></div></article>`;}).join(''):empty('这一组没有结果','可切换其他分组；未收录的入学期不会自动套用旧年份要求。')}</section><p class="feedback-line">结论仅判断已收录的公开申请条件，录取由学校评审决定。材料准备状态和申请窗口单独显示。</p>`;}
async function profileTab(tab){const id=$('#profile-content').dataset.student,s=student(id);$$('[data-act="profile-tab"]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(tab==='results'){if(match)renderMatches();else $('#profile-content').innerHTML=empty('尚未进行匹配','点击上方“开始匹配”查看条件与证据。');}
if(tab==='materials'){const all=new Map();data.programs.forEach(p=>p.materials.forEach(m=>{if(!all.has(m.id))all.set(m.id,{...m,programs:[]});all.get(m.id).programs.push(p.id);}));$('#profile-content').innerHTML=`<section class="panel"><div class="panel-head"><h2>材料准备</h2><span class="muted small">准备状态与实质资格分开记录</span></div><div class="panel-body"><div class="note section">这里记录材料是否已准备；推荐信数量、文书篇数及适用对象仍以项目详情为准。历史匹配中的材料状态保持原样。</div><form id="materials-form" data-id="${id}"><div class="form-grid">${[...all.values()].map(m=>select(m.label,'material.'+m.id,s.materials?.[m.id]||'unknown',Object.entries(preparationName),`${m.stage} · ${m.required?'按适用条件必需':'可选'} · ${m.programs.join(' / ')}`)).join('')}</div><div class="form-actions"><button class="btn primary" type="submit">保存准备状态</button></div></form></div></section>`;}
if(tab==='candidates'){const checks=await api('/combination',{selections:s.candidates||[]});$('#profile-content').innerHTML=`<section class="panel section"><div class="panel-head"><h2>候选清单</h2><span class="muted small">单项目匹配后，再核对申请组合</span></div>${s.candidates?.length?s.candidates.map(key=>{const [pid,rid]=key.split(':'),p=program(pid),r=p?.rounds.find(r=>r.id===rid);return p&&r?`<div class="file-row"><span class="monogram">${pid}</span><div class="grow"><a href="#program/${pid}"><strong>${esc(p.name)}</strong></a><p class="muted small">${r.intake}入学 · 第${r.period}轮</p></div>${button('移除','candidate',`data-key="${key}" data-student="${id}"`,'sm')}</div>`:'';}).join(''):empty('还没有候选项目','从匹配结果或项目详情加入清单。')}</section><section class="panel"><div class="panel-head"><h2>组合规则检查</h2></div><div class="panel-body">${checks.length?checks.map(c=>`<div class="check ${c.state}">${icon(c.state==='pass'?'check':'alert')}<div><strong>${esc(c.label)}</strong><p class="muted">${esc(c.detail)}</p></div>${evidence(c.source)}</div>`).join(''):'<p class="muted">加入项目后自动检查并申及跨轮规则。</p>'}</div></section>`;}
if(tab==='history'){const hs=await api('/matches?studentId='+encodeURIComponent(id));$('#profile-content').innerHTML=`<section class="panel">${hs.length?hs.map(h=>`<div class="timeline-row"><small class="muted">${fmt(h.createdAt)}</small><div><strong>${h.simulation?'模拟':'实际成绩'}匹配</strong><p>${esc(h.actor)} · 符合 ${h.counts.pass} / 附条件 ${h.counts.conditional} / 待核实 ${h.counts.unknown} / 不满足 ${h.counts.fail}</p></div><div class="flex">${button('查看快照','load-match',`data-id="${h.id}"`,'sm')}${button('与最新规则比较','compare-match',`data-id="${h.id}"`,'sm')}</div></div>`).join(''):empty('尚无匹配历史')}</section>`;}}
function programsPage(){ $('#main').innerHTML=pageHead('学校与项目','浏览同一套已核对规则，快速找到项目之间的差别。',button(icon('compare')+' 比较项目','compare-programs'))+`<section class="panel"><div class="toolbar"><label class="search">${icon('search')}<input id="program-search" aria-label="搜索学校或项目" placeholder="搜索学校、项目、专业方向"></label><div class="flex">${select('入学期','program-intake','',[['','全部入学期'],['2027-04','2027年4月'],['2027-09','2027年9月']])}${tag(`${data.programs.length} 个项目`)}</div></div><div id="program-list"></div></section>`;renderProgramRows();}
function renderProgramRows(){const q=($('#program-search')?.value||'').toLowerCase(),intake=$('[name="program-intake"]')?.value;const pp=data.programs.filter(p=>[p.id,p.name,p.school,p.englishName,p.direction].join(' ').toLowerCase().includes(q)&&(!intake||p.rounds.some(r=>r.intake===intake)));$('#program-list').innerHTML=pp.length?pp.map(p=>`<article class="program-card"><div class="between"><div class="program-heading"><span class="monogram">${p.id}</span><div><h2><a href="#program/${p.id}">${esc(p.name)}</a></h2><span class="muted small">${esc(p.school)} · ${esc(p.direction)}</span></div></div><label class="checkbox-label"><input type="checkbox" data-compare="${p.id}" ${selectedCompare.has(p.id)?'checked':''}>比较</label></div><p>${esc(p.englishName)}</p><div class="program-footer">${tag(p.degree)}${tag([...new Set(p.rounds.map(r=>r.intake))].join(' / '))}${badge(p.interview.status==='not-required'?'无面试':p.interview.status==='conditional'?'必要时面试':'入围面试',p.interview.status==='not-required'?'pass':'')}<span class="muted small">规则 v${p.version}</span><a class="btn sm" style="margin-left:auto" href="#program/${p.id}">查看要求 ${icon('arrow')}</a></div></article>`).join(''):empty('没有符合筛选条件的项目');}
function requirementsRows(rows){return rows.map(r=>`<div class="requirement"><div class="between"><h3>${esc(r.topic)}</h3><span>${tag(r.stage)} ${evidence({sourceId:'aohb27',page:r.page,quote:r.evidence,ruleId:r.id})}</span></div><p>${esc(r.detail)}</p>${r.nature==='建议'?badge('建议，不作硬性排除','conditional'):''}</div>`).join('');}
function projectPage(id){const p=program(id);if(!p){$('#main').innerHTML=empty('项目不存在');return;}$('#main').innerHTML=renderProjectDetail(p,{esc,icon,tag,button,evidence,requirementsRows,showSources:showDetailedSources});const section=location.hash.split('/')[2];if(section)setTimeout(()=>$('#detail-'+section)?.scrollIntoView({block:'start'}),30);}

function askPage(){ $('#main').innerHTML=pageHead('条件问答','把问题变成可核对的条件，答案落实到具体项目。')+`<div class="content-width"><form id="ask-form" class="query-box section"><label for="question" class="sr-only">你的选校问题</label><textarea id="question" class="query-input" placeholder="例如：不需要 SAT 或 ACT，雅思 6 分可以申请哪些项目？">${esc(queryDraft?.text||'')}</textarea><div class="query-tools"><span class="muted small flex">${icon('search')}${data.capabilities.model?'语言模型辅助理解 · 依据已核对规则回答':'本地条件检索 · 支持考试、分数、入学期、面试等'}</span><button class="btn primary" type="submit">查询项目 ${icon('arrow')}</button></div></form><div class="flex wrap section">${['只有托福成绩就能申请的学校','2027年9月不需要面试的项目','哪些项目接受多邻国？','各项目的学费是多少？'].map(q=>`<button class="suggestion" data-act="ask-preset" data-question="${q}">${q}</button>`).join('')}</div><div id="query-conditions"></div><div id="query-results"></div></div>`;if(queryDraft)renderQueryConditions();if(queryResult)renderQueryResults();}
function renderQueryConditions(){if(!queryDraft)return;const q=queryDraft;$('#query-conditions').innerHTML=`${q.clarification?`<div class="note warning section"><strong>${esc(q.clarification)}</strong><p>请选择你的意思，避免把不同条件混为一谈。</p><div class="flex wrap" style="margin-top:12px">${button('英语证明只提交这一种考试','clarify',`data-choice="language"`,'sm')}${button('不另交SAT／ACT等学术考试','clarify',`data-choice="academic"`,'sm')}</div></div>`:''}<section class="query-conditions"><div class="between" style="margin-bottom:14px"><h3>我理解的筛选条件</h3><span class="muted small">可直接修正</span></div><form id="query-filter-form">${select('语言考试','exam',q.exam||'',[['','不限定'],...exams])}${field('考试成绩','maxScore',q.maxScore??'','number')}${select('目标入学','intake',q.intake||'',[['','全部已收录入学期'],['2027-04','2027年4月'],['2027-09','2027年9月']])}${select('学术考试','academic',q.academic,[['any','不限定'],['not-required','无须提交SAT／ACT']])}${select('面试','interview',q.interview,[['any','不限定'],['not-required','明确不需要面试']])}<button class="btn" type="submit" ${q.clarification?'disabled':''}>更新结果</button></form><p class="feedback-line">${esc(q.parserNote||'分数筛选仅比较对应总分／指定单项；有效期、考试形式及单项须结合学生核对。')}</p></section>`;}
function renderQueryResults(){const r=queryResult;if(!r)return;$('#query-results').innerHTML=`<div class="query-results"><div class="between section"><div><h2>${r.unsupported?.length?'资料范围不足':r.matched.length?`找到 ${r.matched.length} 个相关项目`:'没有已确认符合的项目'}</h2><p class="muted small">${esc(r.coverage)}</p></div></div>${r.unsupported?.length?`<div class="note warning">${r.unsupported.map(esc).join('<br>')}</div>`:''}${r.matched.length?`<section class="panel section">${r.matched.map(x=>queryCard(x,false)).join('')}</section>`:''}${r.uncertain?.length?`<h3 class="section">另有 ${r.uncertain.length} 个项目需要核实</h3><section class="panel section">${r.uncertain.map(x=>queryCard(x,true)).join('')}</section>`:''}${!r.matched.length&&!r.uncertain?.length&&!r.unsupported?.length?empty('没有符合本次条件的已收录项目','可以放宽筛选条件；本结果不代表其他学校或未收录年份。'):''}<div class="note">学历、文书、推荐信等其他要求仍需满足。“未注明”不等于“不需要”。如需判断具体学生，请关联学生档案。</div></div>`;}
function queryCard(x,uncertain){return `<article class="query-result"><div class="between"><div class="flex"><span class="monogram">${x.id}</span><div><h3><a href="#program/${x.id}">${esc(x.name)}</a></h3><span class="muted small">${esc(x.school)} · 规则 v${x.version}</span></div></div>${badge(uncertain?'待核实':'符合查询条件',uncertain?'unknown':'pass')}</div><ul>${x.reasons.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="flex wrap">${x.sources.filter((s,i,a)=>a.findIndex(v=>String(v.page)===String(s.page))===i).slice(0,6).map(evidence).join('')}<a class="btn sm" style="margin-left:auto" href="#program/${x.id}">查看完整要求</a>${button('关联学生','select-student',`data-id="${x.id}"`,'sm')}</div></article>`;}

function studentForm(s){studentDraft=structuredClone(s||{name:'',intake:'2027-09',exams:[],materials:{},waiver:{},candidates:[]});const d=studentDraft;showModal(s?'编辑学生档案':'新建学生档案',`<form id="student-form"><div class="form-tabs">${['基本信息','学历与资格','语言与考试','其他信息'].map((t,i)=>`<button type="button" class="tab ${i===0?'active':''}" data-act="student-step" data-step="${i}">${i+1}. ${t}</button>`).join('')}</div><section data-step-panel="0"><details><summary>从一段文字整理信息</summary><div>${textArea('粘贴学生情况','studentText','','3')}${button(icon('spark')+' 整理到表单','parse-student','','sm')}<div id="parse-notes"></div></div></details><div class="form-grid">${field('学生姓名 *','name',d.name)}${field('出生日期','birthDate',d.birthDate,'date')}${field('就读学校','school',d.school)}${select('目标入学期','intake',d.intake,[['','待确定'],['2027-04','2027年4月'],['2027-09','2027年9月']])}${field('国籍（多国籍用逗号分隔）','nationalities',(d.nationalities||[]).join('，'))}${field('当前居住地 / 居留身份','residence',d.residence)}${triField('持有效日本居留身份','inJapanResident',d.inJapanResident)}${triField('是否属于澳大利亚国内学生类别','australianDomestic',d.australianDomestic,'GLA专用：澳洲公民、永居、人道签证及指定新西兰身份；不确定时保留待核实。')}</div></section><section class="hidden" data-step-panel="1"><div class="form-grid">${select('课程体系','curriculum',d.curriculum,[['','待核实'],'普通高中','IB','A-Level','美国高中','加拿大高中','澳大利亚高中','GED','其他'])}${select('实际／预计取得的完整资格','qualification',d.qualification,[['','待核实'],'普通高中','IB Diploma','GCE A-Level','International A-Level','Abitur','Baccalaureate','European Baccalaureate','GED','OSSD','其他'])}${select('资格取得状态','educationStatus',d.educationStatus,[['','待核实'],['completed','已取得'],['expected','预计取得（校方允许）']])}${field('资格取得／预计毕业日期','graduationDate',d.graduationDate,'date')}${triField('标准12年教育（或已认可等同课程）','standard12',d.standard12)}${triField('仅以日本専修学校高等课程资格申请','japanVocationalOnly',d.japanVocationalOnly,'JDP特有限制；不要把其他职业教育一概视为此类。')}${field('GPA（若有）','academic.gpa',d.academic?.gpa,'number')}${field('GPA满分口径','academic.scale',d.academic?.scale,'number')}<div class="span2">${textArea('科目、层级与成绩（每行一项）','subjectNotes',d.subjectNotes||'',3)}</div></div><details><summary>其他资格路径、认证与学制</summary><div class="form-grid">${triField('12年国际学校课程','international12',d.international12)}${select('学校认证','accreditation',d.accreditation,[['','待核实'],'WASC','NEASC','Cognia','COBIS','CIS','ACSI','其他'])}${triField('日本境内MEXT指定12年国际学校','japanDesignated12',d.japanDesignated12)}${triField('MEXT指定11年课程（已核对）','designated11',d.designated11)}${triField('少于12年的本国学校教育','shortSchool',d.shortSchool)}${triField('MEXT指定大学预备教育','preparatory',d.preparatory)}${triField('通过海外12年教育同等学力考试','equivalency',d.equivalency)}${triField('通过日本高卒认定','japanEquivalency',d.japanEquivalency)}${triField('已取得RU个别资格认定','individualReview',d.individualReview)}</div></details></section><section class="hidden" data-step-panel="2"><div class="between"><h3>每次考试单独记录</h3>${button(icon('plus')+' 添加成绩','add-exam','','sm')}</div><p class="muted small">保留考试日期、量表、总分和单项，不自动组合最高分。</p><div id="exam-blocks">${examBlocks(d.exams)}</div><details><summary>英语成绩豁免条件</summary><div class="form-grid">${triField('入学日前最近6年正式教育仅英语','waiver.sixYears',d.waiver?.sixYears,'GS / CRPS / ISSE；需核对整个6年期间。')}${triField('IB教学和考核全英语','waiver.ibEnglish',d.waiver?.ibEnglish,'GLA；除专门语言课程外。')}${triField('GLA Group A 国籍已核对','waiver.groupACitizen',d.waiver?.groupACitizen)}${triField('GLA指定体系至少1年Year 11/12英语教育','waiver.groupAEducation',d.waiver?.groupAEducation)}${triField('JDP指定体系Grade 9–12四年仅英语','waiver.jdpFourYears',d.waiver?.jdpFourYears)}${triField('JDP期间未修读ESL','waiver.noESL',d.waiver?.noESL)}</div></details></section><section class="hidden" data-step-panel="3"><div class="form-grid">${select('专业偏好','direction',d.direction,[['','不限定'],'人文与综合','国际关系','社会与政策','计算机与工程'])}${field('每学年学费预算（日元，可选）','budget',d.budget,'number')}${triField('可满足赴美财力要求（适用时）','financeSufficient',d.financeSufficient,'实质条件与财力证明是否已开具分别记录；不作当前申请门槛。')}<div class="span2">${textArea('顾问备注','notes',d.notes||'',4)}</div></div><div class="note" style="margin-top:20px">学校未注明的金额或门槛不会被自动补齐。预算及专业偏好单独筛选。</div></section><div class="form-actions"><span class="muted small" style="margin-right:auto">保存后团队可见</span>${button('取消','close')}<button class="btn primary" type="submit">保存学生档案</button></div></form>`,true);}
function examBlocks(list){return list.length?list.map((e,i)=>`<div class="exam-block"><div class="between"><h3>第 ${i+1} 次考试</h3>${button('移除','remove-exam',`data-index="${i}"`,'sm ghost')}</div><div class="exam-grid">${select('考试','exam.'+i+'.exam',e.exam||'TOEFL iBT',exams)}${select('成绩状态','exam.'+i+'.status',e.status||'actual',[['actual','实际取得'],['target','目标分数（模拟）']])}${field('总分／指定单项','exam.'+i+'.score',e.score,'number')}${select('TOEFL量表','exam.'+i+'.scale',e.scale,[['','待核实／不适用'],['0–120','0–120'],['1–6','1–6']])}${field('考试日期','exam.'+i+'.date',e.date,'date')}${field('成绩可取得日期','exam.'+i+'.availableDate',e.availableDate,'date')}${select('考试形式','exam.'+i+'.format',e.format,[['','待核实'],['center','常规官方考试（含DET）'],['home','TOEFL Home Edition'],['essentials','TOEFL Essentials'],['online','IELTS Online'],['one-skill','IELTS单科重考'],['institutional','机构考试 / TOEIC IP']])}${select('是否跨次拼分','exam.'+i+'.superscore',e.superscore??false,[['false','否，单次考试'],['true','是']])}${['reading','listening','writing','speaking'].map((k,j)=>field(['阅读','听力','写作','口语'][j],'exam.'+i+'.'+k,e[k],'number')).join('')}</div></div>`).join(''):`<div class="empty" style="padding:25px">还没有考试记录；可添加成绩，或填写下方豁免条件。</div>`;}
function gatherStudent(){const f=$('#student-form'),d=structuredClone(studentDraft),values=new FormData(f),booleans=['inJapanResident','australianDomestic','standard12','japanVocationalOnly','international12','japanDesignated12','designated11','shortSchool','preparatory','equivalency','japanEquivalency','individualReview','financeSufficient'];for(const [k,v] of values){if(k==='studentText')continue;if(k.startsWith('exam.')){const [,i,key]=k.split('.');d.exams[i]??={id:crypto.randomUUID()};d.exams[i][key]=['score','reading','listening','writing','speaking'].includes(key)?(v===''?null:Number(v)):key==='superscore'?v==='true':v;}else if(k==='nationalities')d.nationalities=v.split(/[,，、]/).map(s=>s.trim()).filter(Boolean);else if(booleans.includes(k)||k.startsWith('waiver.'))setValue(d,k,v===''?null:v==='true');else if(['budget','academic.gpa','academic.scale'].includes(k))setValue(d,k,v===''?null:Number(v));else setValue(d,k,v.trim());}return d;}
function editor(p,copy=false){editDraft=structuredClone(p);if(copy){editDraft.id='';editDraft.version=0;editDraft.school='';editDraft.name='';editDraft.reviewNote='';}const d=editDraft;showModal(copy?'复制为新项目':'编辑项目规则 · '+p.id,`<form id="program-form"><div class="note section">${copy?'所有复制条件都需按新项目原文重新核对。':'保存后立即影响新的查询和匹配；历史结果保留原规则。'} 请填写原文依据，其他员工可查看修改记录。</div><div class="form-grid">${field('项目编号','id',d.id)}${field('项目名称','name',d.name)}${field('学校','school',d.school)}${field('英文全称','englishName',d.englishName)}${field('入学年份','year',d.year,'number')}${select('专业方向','direction',d.direction,['人文与综合','国际关系','社会与政策','计算机与工程'])}${field('招生通道','channel',d.channel)}${field('学位类型','degree',d.degree)}</div><details open><summary>学费、筛选与组合申请</summary><div class="form-grid">${select('学费公布状态','tuition.status',d.tuition.status,[['unspecified','未注明'],['published','已公布']])}${field('学费金额','tuition.amount',d.tuition.amount,'number')}${select('币种','tuition.currency',d.tuition.currency,['JPY','USD','AUD','CNY'])}${select('计费周期','tuition.period',d.tuition.period,['学年','学期','全程'])}${select('面试','interview.status',d.interview.status,[['not-required','明确不要求'],['conditional','必要时要求'],['required','入围者必须参加'],['unspecified','未注明']])}${field('筛选说明','interview.detail',d.interview.detail)}${select('学术标准化考试','academicTests.status',d.academicTests.status,[['optional','可选'],['not-required','明确不要求'],['required','必需'],['unspecified','未注明']])}${select('允许多项目并申','combination.parallel',d.combination.parallel,[['allowed','允许'],['forbidden','不允许'],['unspecified','未注明']])}${select('允许跨轮重申','combination.reapply',d.combination.reapply,[['allowed','允许'],['forbidden','不允许'],['unspecified','未注明']])}${field('推荐信复用说明','combination.referenceReuse',d.combination.referenceReuse)}${field('材料复用说明','combination.materials',d.combination.materials)}</div></details><details><summary>语言考试门槛（${d.language.length}条）</summary><div><div class="form-grid section">${field('成绩有效年数','languagePolicy.validYears',d.languagePolicy.validYears,'number')}${triField('校方明确允许跨次拼分','languagePolicy.allowSuperscore',d.languagePolicy.allowSuperscore)}</div><div class="table-wrap"><table class="score-table"><thead><tr><th>考试</th><th>总分</th><th>读</th><th>听</th><th>写</th><th>说</th><th>来源页码</th></tr></thead><tbody>${d.language.map((l,i)=>`<tr><td>${esc(l.exam)}<br><small>${esc(l.scale==='未注明'?'':l.scale)}</small></td>${['score','reading','listening','writing','speaking'].map(k=>`<td><input class="small-input" aria-label="${esc(l.exam+' '+l.scale+' '+k)}" name="language.${i}.${k}" type="number" min="0" step="any" value="${typeof l[k]==='number'?l[k]:''}"></td>`).join('')}<td><input class="small-input" aria-label="来源页码" name="language.${i}.source.page" value="${esc(l.source.page)}"></td></tr>`).join('')}</tbody></table></div><p class="feedback-line">空白单项保留为“未注明”；总分必须填写。计分版本按考试日期使用。</p></div></details><details><summary>学历路径与豁免条件</summary><div><p class="muted small section">每组内的条件须同时满足；学历路径和豁免路径分别满足其中一组即可。</p>${[['paths','学历路径'],['waivers','豁免路径']].map(([type,title])=>d[type].map((path,i)=>`<h3>${title} ${esc(path.id)} · ${esc(path.label)}</h3>${path.all.map((r,j)=>`<div class="rule-value"><label>${esc(r.label)}</label><span class="muted">${({eq:'等于',neq:'不等于',in:'其中之一',gte:'不低于',lte:'不高于',contains:'包含'})[r.op]}</span>${typeof r.value==='boolean'?`<select name="condition.${type}.${i}.${j}" aria-label="${esc(r.label)}"><option value="true" ${r.value?'selected':''}>是</option><option value="false" ${!r.value?'selected':''}>否</option></select>`:`<input name="condition.${type}.${i}.${j}" aria-label="${esc(r.label)}" value="${esc(Array.isArray(r.value)?r.value.join(' | '):r.value)}">`}</div>`).join('')}`).join('')).join('')}<p class="feedback-line">列表值使用 | 分隔。新增条件字段和运算关系需在规则结构中定义，不能只改说明文字。</p></div></details><details><summary>申请轮次与日期</summary><div class="stack">${d.rounds.map((r,i)=>`<div class="exam-block"><h3>${r.intake} · 第${r.period}轮</h3><div class="form-grid">${field('入学期','rounds.'+i+'.intake',r.intake)}${field('轮次','rounds.'+i+'.period',r.period,'number')}${field('申请开始','rounds.'+i+'.applyStart',r.applyStart,'date')}${field('申请截止','rounds.'+i+'.applyEnd',r.applyEnd,'date')}${field('入学日','rounds.'+i+'.enrollmentDate',r.enrollmentDate,'date')}${field('结果公布','rounds.'+i+'.final',r.final,'date')}</div></div>`).join('')}</div></details><details><summary>其他证明材料</summary><div id="editor-materials">${d.materials.map((m,i)=>`<div class="editor-row">${field('材料名称','materials.'+i+'.label',m.label)}${select('必要性','materials.'+i+'.required',m.required,[['true','必需（按适用范围）'],['false','可选']])}${select('适用阶段','materials.'+i+'.stage',m.stage,['申请','录取后','入学前','入学后','赴AU前'])}</div>`).join('')}${button(icon('plus')+' 增加材料条目','add-material','','sm')}</div></details><details><summary>完整规则结构（高级维护）</summary><div><p class="muted small section">用于新增学校、课程、考试、适用条件或来源。开启后以此结构替代上面的表单值，保存前仍执行校验。</p><label class="checkbox-label section"><input type="checkbox" name="useStructure">使用完整结构作为本次保存内容</label>${textArea('完整规则','structure',JSON.stringify(d,null,2),18)}</div></details><div class="form-section"><h3>修改依据</h3>${textArea('请记录来源文件、页码及修改原因 *','note','',3)}</div><div class="form-actions"><span class="muted small" style="margin-right:auto">${copy?'新项目':'正在编辑 v'+p.version}</span>${button('取消','close')}<button class="btn primary" type="submit">保存并立即生效</button></div></form>`,true);if(!copy)$('[name="id"]').readOnly=true;}
function gatherProgram(){const d=structuredClone(editDraft),fd=new FormData($('#program-form'));if(fd.get('useStructure'))return {program:JSON.parse(fd.get('structure')),note:fd.get('note')};for(const [k,v] of fd){if(['structure','note','useStructure'].includes(k))continue;if(k.startsWith('condition.')){const [,type,i,j]=k.split('.'),r=d[type][i].all[j];r.value=Array.isArray(r.value)?v.split('|').map(s=>s.trim()).filter(Boolean):typeof r.value==='boolean'?v==='true':typeof r.value==='number'?Number(v):v;}else if(k.startsWith('language.')&&['score','reading','listening','writing','speaking'].includes(k.split('.').at(-1)))setValue(d,k,v===''?(k.endsWith('.score')?null:'未注明'):Number(v));else if(['year','tuition.amount','languagePolicy.validYears'].includes(k)||/^rounds\.\d+\.period$/.test(k))setValue(d,k,v===''?null:Number(v));else if(k==='languagePolicy.allowSuperscore'||/^materials\.\d+\.required$/.test(k))setValue(d,k,v==='true');else setValue(d,k,v);}if(d.tuition.status==='unspecified')d.tuition.amount=null;return {program:d,note:fd.get('note')};}
function libraryPage(){ $('#main').innerHTML=pageHead('资料维护','从原始文件到可判断的规则，每一步保留依据。',button(icon('plus')+' 新增项目','new-project'))+`<div class="workspace-columns"><div><section class="panel section"><div class="panel-head"><h2>招生资料</h2><span class="muted small">提取后须员工核对</span></div>${data.documents.map(d=>`<div class="file-row">${icon('file')}<div class="grow"><strong>${esc(d.name)}</strong><p class="muted small">${d.builtin?'2027入学 · 23页 · 已核对资料':`${esc(d.uploadedBy)} · ${fmt(d.uploadedAt)}`}</p></div>${badge(({ready:'已核对',uploaded:'待解析',parsing:'解析中',review:'待核对',error:'解析失败'})[d.status]||d.status,d.status==='ready'?'pass':d.status==='error'?'fail':'unknown')}${d.builtin?`<a class="btn sm" href="/sources/aohb27.pdf" target="_blank" rel="noopener">原文</a>`:button('查看','document',`data-id="${d.id}"`,'sm')}</div>`).join('')}<div class="panel-body"><form id="upload-form" class="dropzone">${icon('upload')}<h3>添加新的招生文件</h3><p>PDF、TXT 或 Markdown，最大25MB。原始文件保留在团队服务器。</p><input type="file" id="upload-file" accept=".pdf,.txt,.md" required aria-label="选择招生文件"><div style="margin-top:18px"><button class="btn" type="submit">上传资料</button></div></form></div></section><section class="panel"><div class="panel-head"><h2>项目规则</h2><span class="muted small">员工保存后立即生效</span></div>${data.programs.map(p=>`<div class="file-row"><span class="monogram">${p.id}</span><div class="grow"><strong>${esc(p.name)}</strong><p class="muted small">${p.year} · ${esc(p.school)} · 当前 v${p.version}</p></div>${button('修改记录','program-history',`data-id="${p.id}"`,'ghost sm')}${button('编辑规则','edit-program',`data-id="${p.id}"`,'sm')}</div>`).join('')}</section></div><aside class="right-rail"><section class="panel mini section"><h3>核对流程</h3><div class="stack"><p><strong>1. 上传招生原文</strong><br>保留原文件，PDF由本机MinerU解析。</p><p><strong>2. 查看提取建议</strong><br>核对项目、年份、路径、例外与来源页码。</p><p><strong>3. 保存项目规则</strong><br>校验通过后立即生效，并保留前后版本。</p></div></section><div class="note">自动提取结果只作为建议。资料冲突由员工核对后处理，无管理员审批步骤。</div></aside></div>`;}
async function documentDialog(id){const d=await api('/documents/'+id);showModal(d.name,`<div class="between section"><div>${badge(({uploaded:'待解析',parsing:'解析中',review:'待核对',error:'解析失败'})[d.status]||d.status,d.status==='error'?'fail':'unknown')} <a class="link" href="/uploads/${d.id}" target="_blank" rel="noopener">查看原文件</a></div><div class="flex">${button('刷新状态','document',`data-id="${id}"`,'sm')}${d.status!=='parsing'?button('本机解析并提取建议','parse-document',`data-id="${id}"`,'primary sm'):''}</div></div>${d.error?`<div class="error-box">${esc(d.error)}</div>`:''}${d.status==='parsing'?'<div class="note">正在本机解析；可以关闭窗口继续工作，稍后刷新查看结果。</div>':''}${d.suggestions?.length?`<div class="note section">以下为关键词定位建议，行号不是PDF页码。编辑项目规则时请核对原文页码、条件关系与适用范围。</div><div class="section">${select('选择需要更新的项目','document-project',data.programs[0].id,data.programs.map(p=>[p.id,p.id+' · '+p.name]))}${button('打开项目规则编辑','edit-document-project',`data-document="${id}"`,'primary sm')}</div>${d.suggestions.map(s=>`<div class="requirement"><div class="flex wrap">${s.fields.map(tag).join('')}<span class="muted small">提取文本第${s.line}行</span></div><p>${esc(s.text)}</p></div>`).join('')}`:d.status==='review'?empty('没有发现已识别的字段关键词','可直接阅读提取文本，人工补充项目规则。'):''}${d.text?`<details><summary>完整提取文本</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere;max-height:500px;overflow:auto">${esc(d.text)}</pre></details>`:''}`,true);}
async function historyPage(){const [events,versions]=await Promise.all([api('/events'),api('/versions')]);$('#main').innerHTML=pageHead('修改记录','查看谁修改了什么，按项目完整版本回档。')+`<div class="workspace-columns"><section class="panel"><div class="panel-head"><h2>团队操作记录</h2><span class="muted small">最近200条</span></div>${events.length?events.map(e=>`<div class="timeline-row"><span class="muted small">${fmt(e.created_at)}</span><div><strong>${esc(e.actor)}</strong> <span>${({rule:'修改了项目',restore:'回档了项目',student:'更新了学生',match:'执行了匹配',document:'处理了文件',account:'创建了账号',initialize:'初始化了'})[e.kind]||e.kind} <strong>${esc(e.subject)}</strong></span><p>${esc(e.detail.note||e.detail.action||'')}${e.detail.from?' · v'+e.detail.from+' → v'+e.detail.to:''}</p></div>${e.kind==='rule'||e.kind==='restore'?button('查看版本','program-history',`data-id="${e.subject}"`,'sm'):e.kind==='student'?button('查看差异','event-detail',`data-id="${e.id}"`,'sm'):''}</div>`).join(''):empty('还没有修改记录')}</section><aside class="right-rail"><section class="panel mini section"><h3>项目版本</h3>${data.programs.map(p=>`<div class="project-mini"><span class="monogram">${p.id}</span><div><strong>当前 v${p.version}</strong><p class="muted small">${versions.filter(v=>v.program_id===p.id).length}个历史版本</p></div>${button('查看','program-history',`data-id="${p.id}"`,'ghost sm')}</div>`).join('')}</section><div class="note">回档会生成一个新版本，中间版本及原操作记录均保留。已保存的匹配不会被静默改写。</div></aside></div>`;}
async function versionsDialog(id){const vs=await api('/versions?programId='+id),p=program(id);showModal(id+' · 规则版本',`<div class="note section">当前使用 v${p.version}。回档以该项目的完整规则为单位。</div>${vs.map((v,i)=>`<section class="version-box section"><div class="between"><strong>v${v.version} ${v.version===p.version?tag('当前'):''}</strong><span class="muted small">${fmt(v.created_at)} · ${esc(v.actor)}</span></div><p class="muted small" style="margin:9px 0">${esc(v.note)}</p><div class="flex">${button('查看变更','version-diff',`data-id="${id}" data-version="${v.version}"`,'sm')}${v.version!==p.version?button('回档到此版本','restore',`data-id="${id}" data-version="${v.version}" data-current="${p.version}"`,'sm'):''}</div></section>`).join('')}`,true);}
async function settingsPage(){const team=await api('/team');$('#main').innerHTML=pageHead('团队设置','员工账号与共享工作空间。')+`<div class="grid2"><section class="panel"><div class="panel-head"><h2>团队成员</h2></div>${team.users.map(u=>`<div class="file-row"><div class="avatar">${esc(u.login[0])}</div><div class="grow"><strong>${esc(u.login)}</strong><p class="muted small">${u.role==='admin'?'管理员':'员工'}</p></div>${tag('可编辑规则')}</div>`).join('')}<div class="panel-body"><h3>团队邀请码</h3><p class="muted small section">同事在登录页选择“加入团队”，使用此码创建自己的账号。</p><div class="flex"><input aria-label="团队邀请码" readonly value="${esc(team.invite)}" style="max-width:100%;padding:10px;border:1px solid var(--line);border-radius:6px;flex:1">${button('复制','copy-invite',`data-value="${team.invite}"`,'sm')}</div></div></section><div class="stack"><section class="panel panel-body"><h2>数据备份</h2><p class="muted" style="margin:12px 0 20px">导出学生、项目规则、版本、匹配快照和操作记录。备份包含学生信息，请在公司内部保存。</p><a class="btn" href="/api/export">${icon('download')}导出数据备份</a></section><section class="panel panel-body"><h2>连接状态</h2><div class="check">${icon('check')}团队数据库已连接</div><div class="check">${icon(data.capabilities.mineru?'check':'alert')}本机文件解析：${data.capabilities.mineru?'已配置MinerU':'尚未配置'}</div><div class="check">${icon(data.capabilities.model?'check':'search')}问题理解：${data.capabilities.model?'语言模型辅助':'本地条件解析'}</div><p class="muted small">高级语义理解可通过服务器环境变量连接模型；未配置时，界面明确显示本地条件检索。</p></section></div></div>`;}
function authPage(setup=false,join=false){$('#app').innerHTML=`<div class="auth-page"><section class="auth-intro"><a class="brand" href="#"><span class="brand-mark">${icon('graduation')}</span><span class="brand-text"><strong>SGU</strong><small>日本本科选校工作台</small></span></a><div><h1>从学生出发，<br>让选校有据可依。</h1><p>整理申请条件，核对每条路径。<br>把经验留给咨询，把证据留在这里。</p><div class="auth-visual"><div class="auth-path">${icon('students')}学生情况与项目要求逐项匹配</div><div class="auth-path">${icon('ask')}用一个问题，找到具体项目</div><div class="auth-path">${icon('file')}每条条件，回到招生原文</div></div></div><small style="color:#b8d0c1">团队共享 · 即时更新 · 历史可追溯</small></section><section class="auth-form"><form id="auth-form" data-register="${setup||join}"><h2>${setup?'创建团队工作空间':join?'加入团队':'欢迎回到工作台'}</h2><p>${setup?'设置管理员账号，开始维护选校资料。':join?'填写同事提供的邀请码，使用个人账号协作。':'登录后查看团队学生、项目与匹配记录。'}</p>${field('账号','login','','text','使用字母、数字或邮箱，至少3个字符')}${field('密码','password','','password',setup||join?'至少8位字符':'')}${join?field('团队邀请码','invite',''):''}<button type="submit" class="btn primary">${setup?'创建工作空间':join?'创建员工账号':'登录工作台'} ${icon('arrow')}</button>${!setup?`<div class="split-note">${join?'已有账号？':'第一次使用？'}</div>${button(join?'返回登录':'加入已有团队',join?'login-view':'join-view','','ghost')}`:''}<p class="muted small" style="margin-top:28px">所有员工可编辑项目规则，系统记录修改人和版本。</p></form></section></div>`;}
async function route(){if(!data)return;const epoch=++routeEpoch;shell();$('#main').innerHTML='<div class="loading">正在加载…</div>';const [key='students',id]=location.hash.slice(1).split('/');try{if(key==='students'||!key)dashboard();else if(key==='student')await profile(id);else if(key==='programs')programsPage();else if(key==='program')projectPage(id);else if(key==='ask')askPage();else if(key==='library')libraryPage();else if(key==='history')await historyPage();else if(key==='settings')await settingsPage();else dashboard();}catch(e){if(epoch===routeEpoch)$('#main').innerHTML=empty('页面暂时无法加载',e.message);}}

async function runMatch(id,simulation=false){match=await api('/match',{studentId:id,simulation});resultFilter='all';await refreshData();$$('[data-act="profile-tab"]').forEach(b=>b.classList.toggle('active',b.dataset.tab==='results'));renderMatches();toast(simulation?'模拟结果已保存':'匹配完成，已保留本次快照');}
function download(filename,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function diffValues(a,b,path=''){const rows=[];if(JSON.stringify(a)===JSON.stringify(b))return rows;if(a&&b&&typeof a==='object'&&typeof b==='object'){for(const k of new Set([...Object.keys(a),...Object.keys(b)]))rows.push(...diffValues(a[k],b[k],path?path+'.'+k:k));}else rows.push({path,before:a,after:b});return rows;}
function diffTable(rows){return `<div class="table-wrap"><table><thead><tr><th>字段</th><th>修改前</th><th>修改后</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.path)}</td><td style="overflow-wrap:anywhere;max-width:340px">${esc(typeof r.before==='object'?JSON.stringify(r.before):r.before??'未设置')}</td><td style="overflow-wrap:anywhere;max-width:340px">${esc(typeof r.after==='object'?JSON.stringify(r.after):r.after??'未设置')}</td></tr>`).join('')}</tbody></table></div>`;}

document.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b)return;const act=b.dataset.act;try{
if(act==='close')return closeModal();
if(act==='logout'){await api('/auth/logout',{});data=null;auth=null;csrf='';return authPage();}
if(act==='join-view')return authPage(false,true);if(act==='login-view')return authPage();
if(act==='new-student')return studentForm();if(act==='edit-student')return studentForm(student(b.dataset.id));
if(act==='student-filter'){studentFilter=b.dataset.filter;$$('[data-act="student-filter"]').forEach(x=>x.classList.toggle('active',x===b));return renderStudentRows();}
if(act==='student-step'){$$('[data-step-panel]').forEach(x=>x.classList.toggle('hidden',x.dataset.stepPanel!==b.dataset.step));$$('[data-act="student-step"]').forEach(x=>x.classList.toggle('active',x===b));return;}
if(act==='add-exam'){studentDraft=gatherStudent();studentDraft.exams.push({id:crypto.randomUUID(),exam:'TOEFL iBT',status:'actual'});$('#exam-blocks').innerHTML=examBlocks(studentDraft.exams);return;}
if(act==='remove-exam'){studentDraft=gatherStudent();studentDraft.exams.splice(Number(b.dataset.index),1);$('#exam-blocks').innerHTML=examBlocks(studentDraft.exams);return;}
if(act==='parse-student'){const current=gatherStudent(),r=await api('/student-text',{text:$('[name="studentText"]').value});studentForm({...current,...r.fields,exams:[...(current.exams||[]),...(r.fields.exams||[])]});$('#parse-notes').innerHTML=`<div class="note warning" style="margin-top:15px">${r.notes.map(esc).join('<br>')}</div>`;$('.modal details').open=true;toast('已整理，请核对表单后保存');return;}
if(act==='match'||act==='simulate'){b.disabled=true;await runMatch(b.dataset.id,act==='simulate');return;}
if(act==='profile-tab')return await profileTab(b.dataset.tab);
if(act==='result-filter'){resultFilter=b.dataset.filter;return renderMatches();}
if(act==='toggle-result'){const el=$('#result-'+b.dataset.index);el.classList.toggle('hidden');b.setAttribute('aria-expanded',String(!el.classList.contains('hidden')));return;}
if(act==='candidate'){const s=structuredClone(student(b.dataset.student)),key=b.dataset.key;s.candidates||=[];s.candidates=s.candidates.includes(key)?s.candidates.filter(k=>k!==key):[...s.candidates,key];await api('/students',{student:s,expectedRevision:s.revision});await refreshData();if($('[data-act="profile-tab"].active')?.dataset.tab==='candidates')await profileTab('candidates');else if(match)renderMatches();toast('候选清单已更新');return;}
if(act==='load-match'){match=await api('/matches/'+b.dataset.id);resultFilter='all';$$('[data-act="profile-tab"]').forEach(x=>x.classList.toggle('active',x.dataset.tab==='results'));return renderMatches();}
if(act==='compare-match'){const old=await api('/matches/'+b.dataset.id),latest=await api('/match',{studentId:old.student.id,simulation:old.simulation});const rows=latest.results.map(r=>{const o=old.results.find(x=>x.programId===r.programId&&x.roundId===r.roundId);return {path:`${r.programId} ${r.intake} 第${r.round}轮`,before:o?`${stateName[o.state]} / 规则v${o.version}`:'无历史结果',after:`${stateName[r.state]} / 规则v${r.version}`};});showModal('历史与最新结果对比',`<div class="note section">历史：${fmt(old.createdAt)}，学生v${old.student.revision}；最新：学生v${latest.student.revision}。两份快照均已保留。</div>${diffTable(rows)}`,true);return;}
if(act==='export-match')return download(`${match.student.name}_选校匹配.json`,JSON.stringify(match,null,2));
if(act==='toggle-sources'){showDetailedSources=!showDetailedSources;document.body.classList.toggle('show-detailed-sources',showDetailedSources);$$('[data-act=toggle-sources]').forEach(toggle=>toggle.setAttribute('aria-checked',String(showDetailedSources)));return;}
if(act==='evidence'){const s=JSON.parse(b.dataset.source),doc=data.documents.find(x=>x.id===s.sourceId),url=s.sourceId==='aohb27'?'/sources/aohb27.pdf':'/uploads/'+encodeURIComponent(s.sourceId);showModal('原文依据',`<p class="muted">${esc(doc?.name||s.sourceId||'来源待核实')} · 第 ${esc(s.page)} 页 · ${esc(s.ruleId||'')}</p>${s.quote?`<blockquote class="source-quote">${esc(s.quote)}</blockquote>`:'<p style="margin:20px 0">请打开原文件核对该页完整条款和上下文。</p>'}<a class="btn primary" href="${url}#page=${parseInt(s.page)||1}" target="_blank" rel="noopener">打开原文 ${icon('eye')}</a>`);return;}
if(act==='ask-preset'){queryDraft={text:b.dataset.question};queryResult=null;if(location.hash!=='#ask')location.hash='#ask';else askPage();setTimeout(()=>$('#ask-form')?.requestSubmit(),80);return;}
if(act==='clarify'){queryDraft.clarification=null;if(b.dataset.choice==='academic')queryDraft.academic='not-required';renderQueryConditions();queryResult=await api('/query',{query:queryDraft});return renderQueryResults();}
if(act==='select-student'){showModal('选择学生',`<div class="stack">${data.students.map(s=>`<div class="between"><div><strong>${esc(s.name)}</strong> ${s.isExample?tag('示例'):''}<p class="muted small">${esc(s.curriculum)} · ${esc(s.intake)}</p></div>${button('打开并匹配','open-and-match',`data-id="${s.id}"`,'sm')}</div>`).join('')||empty('请先新建学生档案')}</div>`);return;}
if(act==='open-and-match'){const id=b.dataset.id;closeModal();location.hash='#student/'+id;setTimeout(()=>runMatch(id).catch(e=>toast(e.message)),120);return;}
if(act==='edit-program')return editor(program(b.dataset.id));
if(act==='new-project'){showModal('新增项目',`<div class="note section">选择接近的项目作为起点，复制后需按新项目招生原文逐项核对并保存。复制不会自动生效。</div>${select('参考项目','copy-template',data.programs[0].id,data.programs.map(p=>[p.id,p.id+' · '+p.name]))}<div style="margin-top:20px">${button('建立待核对副本','copy-project','','primary')}</div>`);return;}
if(act==='copy-project')return editor(program($('[name="copy-template"]').value),true);
if(act==='add-material'){const current=gatherProgram();editDraft=current.program;editDraft.materials.push({id:'extra-'+crypto.randomUUID().slice(0,8),label:'新的证明材料',required:false,stage:'申请',source:{sourceId:'aohb27',page:1}});editor(editDraft);toast('已增加条目，请填写名称、条件并核对来源');return;}
if(act==='program-history')return await versionsDialog(b.dataset.id);
if(act==='version-diff'){const vs=await api('/versions?programId='+b.dataset.id),v=vs.find(x=>x.version===Number(b.dataset.version)),prev=vs.find(x=>x.version===v.version-1);showModal(`${b.dataset.id} v${v.version} 的变更`,prev?diffTable(diffValues(prev.data,v.data)):`<p class="note">初始版本</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(JSON.stringify(v.data,null,2))}</pre>`,true);return;}
if(act==='restore'){if(!confirm(`将${b.dataset.id}完整规则恢复为v${b.dataset.version}内容，并生成新版本？`))return;await api('/restore',{programId:b.dataset.id,version:Number(b.dataset.version),expectedVersion:Number(b.dataset.current)});await refreshData();toast('已回档并生成新版本');return versionsDialog(b.dataset.id);}
if(act==='event-detail'){const events=await api('/events'),ev=events.find(x=>x.id===b.dataset.id);return showModal('学生资料修改差异',diffTable(diffValues(ev.detail.before||{},ev.detail.after||{})),true);}
if(act==='compare-programs'){const pp=data.programs.filter(p=>selectedCompare.has(p.id));if(pp.length<2)return toast('请先勾选至少两个项目');showModal('项目要求对比',`<div class="compare-grid"><table><thead><tr><th>要求</th>${pp.map(p=>`<th>${p.id} · ${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${[['入学期',p=>[...new Set(p.rounds.map(r=>r.intake))].join(' / ')],['学历路径',p=>p.paths.map(x=>x.id).join(' / ')],['IELTS',p=>p.language.find(l=>l.exam==='IELTS Academic Module')?.score??'未接受'],['TOEFL（1–6）',p=>p.language.find(l=>l.exam==='TOEFL iBT'&&l.scale==='1–6')?.score??'未接受'],['英语豁免',p=>p.waivers.map(w=>w.label).join('；')],['筛选',p=>p.interview.detail],['材料',p=>p.materials.filter(m=>m.id==='essay'||m.id==='reference').map(m=>m.label).join('；')],['学费',p=>p.tuition.status==='published'?`${p.tuition.amount} ${p.tuition.currency}/${p.tuition.period}`:'未注明']].map(([n,fn])=>`<tr><th>${n}</th>${pp.map(p=>`<td>${esc(fn(p))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`,true);return;}
if(act==='document')return await documentDialog(b.dataset.id);
if(act==='parse-document'){await api('/documents/'+b.dataset.id+'/parse',{});toast('已开始本机解析');return documentDialog(b.dataset.id);}
if(act==='edit-document-project'){const d=await api('/documents/'+b.dataset.document),p=program($('[name="document-project"]').value);editor(p);$('[name="note"]').value=`依据上传文件${d.filename}核对；页码：`;return;}
if(act==='copy-invite'){await navigator.clipboard.writeText(b.dataset.value);toast('邀请码已复制');return;}
if(act==='refresh'){await refreshData();return route();}
}catch(err){toast(err.message);if(err.current&&$('.modal form'))formError($('.modal form'),'同事已保存新版本，请保留你的修改并对比后重新编辑。\n'+JSON.stringify(err.current,null,2));}finally{if(b.isConnected)b.disabled=false;}});

document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{
if(form.getAttribute('id')==='auth-form'){const fields=Object.fromEntries(new FormData(form));const r=await api(form.dataset.register==='true'?'/auth/register':'/auth/login',fields);csrf=r.csrf;auth=r.user;await refreshData();return route();}
if(form.getAttribute('id')==='student-form'){const d=gatherStudent();const saved=await api('/students',{student:d,expectedRevision:studentDraft.revision});form.dataset.dirty='false';closeModal();await refreshData();location.hash='#student/'+saved.id;await route();toast('学生档案已保存');return;}
if(form.getAttribute('id')==='materials-form'){const s=structuredClone(student(form.dataset.id));for(const [k,v] of new FormData(form))s.materials[k.slice(9)]=v;await api('/students',{student:s,expectedRevision:s.revision});await refreshData();toast('材料准备状态已保存');return;}
if(form.getAttribute('id')==='ask-form'){const text=$('#question').value.trim();if(!text)return;queryDraft=await api('/query/interpret',{text});queryResult=null;$('#query-results').innerHTML='';renderQueryConditions();if(!queryDraft.clarification){queryResult=await api('/query',{query:queryDraft});renderQueryResults();}return;}
if(form.getAttribute('id')==='query-filter-form'){const f=Object.fromEntries(new FormData(form));queryDraft={...queryDraft,...f,exam:f.exam||null,intake:f.intake||null,maxScore:f.maxScore===''?null:Number(f.maxScore)};queryResult=await api('/query',{query:queryDraft});return renderQueryResults();}
if(form.getAttribute('id')==='program-form'){const prepared=gatherProgram();const saved=await api('/programs',{...prepared,expectedVersion:editDraft.version||undefined});form.dataset.dirty='false';closeModal();await refreshData();location.hash='#program/'+saved.id;await route();toast(`已保存为v${saved.version}，立即生效`);return;}
if(form.getAttribute('id')==='upload-form'){const file=$('#upload-file').files[0];if(!file)return;if(file.size>25*1024*1024)throw new Error('文件最大25MB');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});const doc=await api('/documents',{filename:file.name,base64});await refreshData();libraryPage();toast('文件已上传');return documentDialog(doc.id);}
}catch(err){formError(form,err.message);if(err.current){const prior=document.createElement('details');prior.innerHTML=`<summary>查看服务器当前版本与本次修改的差异</summary>${diffTable(diffValues(err.current,form.getAttribute('id')==='program-form'?gatherProgram().program:gatherStudent()))}<p class="note warning">请复制保留你的修改，关闭编辑后刷新，再基于最新版本重新修改；系统不会覆盖同事的内容。</p>`;form.prepend(prior);}}finally{if(submit?.isConnected)submit.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.id==='student-search')renderStudentRows();if(e.target.id==='program-search')renderProgramRows();const form=e.target.closest('#student-form,#program-form');if(form)form.dataset.dirty='true';});
document.addEventListener('change',e=>{if(e.target.name==='program-intake')renderProgramRows();if(e.target.dataset.compare){e.target.checked?selectedCompare.add(e.target.dataset.compare):selectedCompare.delete(e.target.dataset.compare);}const form=e.target.closest('#student-form,#program-form');if(form)form.dataset.dirty='true';});
document.addEventListener('keydown',e=>{const modal=$('.modal');if(!modal)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const focusable=[...modal.querySelectorAll('button,input,select,textarea,a[href],summary')].filter(x=>!x.disabled&&x.offsetParent!==null),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',route);
setInterval(async()=>{if(!data||document.hidden)return;try{const r=await api('/revision');if(r.revision!==data.revision&&$('#update-banner'))$('#update-banner').innerHTML=`<div class="update-banner"><span>团队资料已有更新，刷新后查看最新内容。当前编辑和历史结果已保留。</span>${button('刷新资料','refresh','','sm')}</div>`;}catch{}},15000);
try{const r=await api('/auth/state');auth=r.user;csrf=r.csrf||'';if(auth){await refreshData();await route();}else authPage(r.setup);}catch(e){$('#app').innerHTML=empty('无法连接工作台',e.message);}

setupDetailHints({esc,showModal});
